"""Publish only aggregate diagnostics and an executable analysis notebook."""
from pathlib import Path
import json,sys
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
import pandas as pd,numpy as np,matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from sklearn.metrics import precision_recall_curve
from sklearn.calibration import calibration_curve
import nbformat
def main():
    m=json.loads((ROOT/'reports/metrics.json').read_text());d=json.loads((ROOT/'reports/data_manifest.json').read_text());dev=pd.read_csv(ROOT/'reports/development.csv');p=pd.read_parquet(ROOT/'reports/test_predictions.parquet')
    plt.rcParams.update({'font.family':'DejaVu Sans','axes.spines.top':False,'axes.spines.right':False,'figure.facecolor':'white','axes.labelcolor':'#26313c'})
    def save(name):plt.tight_layout();plt.savefig(ROOT/f'reports/figures/{name}.png',dpi=160,bbox_inches='tight');plt.close()
    plt.figure(figsize=(9,4));plt.barh(dev.model,dev.average_precision,color=['#a9adb3','#a9adb3','#ed1738','#b6122d']);plt.xlabel('Average precision — development customers');save('development')
    plt.figure(figsize=(9,5))
    for key,color,label in [('selected','#ed1738','Selected'),('logistic_baseline','#687888','Logistic baseline')]:
        precision,recall,_=precision_recall_curve(p.TARGET,p[key+'_score']);plt.plot(recall,precision,label=label,color=color)
    plt.axhline(p.TARGET.mean(),ls='--',color='#929292',label='Prevalence');plt.xlabel('Recall');plt.ylabel('Precision');plt.legend();save('precision_recall')
    plt.figure(figsize=(9,5));plt.plot([0,1],[0,1],ls='--',color='#aaa')
    for key,color,label in [('selected','#ed1738','Selected'),('logistic_baseline','#687888','Logistic baseline')]:
        observed,predicted=calibration_curve(p.TARGET,p[key+'_score'],n_bins=10,strategy='quantile');plt.plot(predicted,observed,'o-',label=label,color=color)
    plt.xlabel('Mean predicted probability');plt.ylabel('Observed positive rate');plt.legend();save('calibration')
    p['decile']=pd.qcut(p.selected_score.rank(method='first'),10,labels=False)+1;dec=p.groupby('decile').TARGET.agg(['size','mean']);dec.to_csv(ROOT/'reports/risk_deciles.csv')
    plt.figure(figsize=(9,4));plt.bar(dec.index,100*dec['mean'],color='#ed1738');plt.axhline(100*p.TARGET.mean(),ls='--',color='#666',label='Overall prevalence');plt.xlabel('Score decile (10 = highest risk)');plt.ylabel('Observed payment difficulty (%)');plt.legend();save('risk_deciles')
    sub=json.loads((ROOT/'reports/subgroups.json').read_text());plt.figure(figsize=(9,4));x=np.arange(len(sub));plt.bar(x-.18,[g['recall'] for g in sub],.36,label='Recall');plt.bar(x+.18,[g['queue_rate'] for g in sub],.36,label='Flagged share',color='#ed1738');plt.xticks(x,[g['group'] for g in sub]);plt.ylabel('Fraction');plt.xlabel('Reported gender — descriptive audit only');plt.legend();save('subgroups')
    cells=[nbformat.v4.new_markdown_cell('# CreditScope — Home Credit Case\n\n**Lucas Menghi** · classificação binária de dificuldade de pagamento. Continuação do projeto de ingestão Oracle [Case Default Risk](https://github.com/lucasmenghi/Case_Default_Risk).\n\nO alvo segue a definição original da competição; não é uma definição universal de default. Não há validação temporal nem decisão automática de crédito.'),nbformat.v4.new_code_cell("from pathlib import Path\nimport json, pandas as pd\nfrom IPython.display import display, Image\nROOT = Path.cwd().parent if Path.cwd().name == 'notebooks' else Path.cwd()\ndef report(name): return json.loads((ROOT / 'reports' / name).read_text())\nmanifest = report('data_manifest.json')\ndisplay(manifest)"),nbformat.v4.new_markdown_cell('## 1. Dados e ponte com o ETL\n307.511 aplicações rotuladas. Comparação dos clientes e dos alvos com o parquet do ETL original. Histórico com datas relativas anteriores ou iguais à aplicação; pagamentos futuros ou sem data excluídos. Fotos retrospectivas ainda não comprovam disponibilidade operacional.'),nbformat.v4.new_code_cell("display(manifest['etl_bridge'])\ndisplay(manifest['date_audit'])\ndisplay(pd.DataFrame({'n': manifest['splits'], 'positive_rate': manifest['target_rates']}))"),nbformat.v4.new_markdown_cell('## 2. Preparação e seleção\nSeparação estratificada por cliente: 60% treino, 10% desenvolvimento, 10% calibração, 5% política e 15% teste final. Imputação e escala da regressão ajustadas somente no treino. LightGBM trata ausentes; categorias desconhecidas têm código reservado. Gênero e identificador não entram no modelo. DAYS_EMPLOYED=365243 é sentinela, não tempo de emprego.'),nbformat.v4.new_code_cell("display(pd.read_csv(ROOT/'reports/development.csv'))\ndisplay(report('frozen_config.json'))\ndisplay(Image(filename=str(ROOT/'reports/figures/development.png')))"),nbformat.v4.new_markdown_cell('## 3. Teste final e calibração\nSeleção por average precision no desenvolvimento. Platt scaling em clientes independentes; percentil 80 em outra partição para o limiar. O teste só é pontuado depois do congelamento. ROC AUC, AP, KS, Brier e capacidade de análise são reportados.'),nbformat.v4.new_code_cell("metrics=report('metrics.json')\ndisplay(pd.DataFrame({k:metrics[k] for k in ['selected','logistic_baseline']}).T)\nfor name in ['precision_recall','calibration','risk_deciles']: display(Image(filename=str(ROOT/f'reports/figures/{name}.png')))"),nbformat.v4.new_markdown_cell('## 4. Cenários de capacidade\nTop 20% por ranking e limiar congelado são análises distintas. A capacidade histórica não prova redução de inadimplência, lucro ou retorno sobre investimento.'),nbformat.v4.new_code_cell("display(pd.DataFrame([{**{'capacity_pct':r['capacity']}, **r['selected']} for r in report('capacity_scenarios.json')]))"),nbformat.v4.new_markdown_cell('## 5. Auditoria e limitações\nGênero excluído das features, mantido apenas para diagnóstico. Excluir uma variável sensível não demonstra equidade: há proxies. Idade permanece no modelo e exige revisão para aplicação real. Scores externos são anonimizados e não têm explicação operacional. Validar tempo, drift, disponibilidade, estabilidade e impactos antes de um piloto com humanos.'),nbformat.v4.new_code_cell("display(pd.DataFrame(report('subgroups.json')))\ndisplay(Image(filename=str(ROOT/'reports/figures/subgroups.png')))"),nbformat.v4.new_markdown_cell('## 6. Reprodução\nBaixe a fonte original respeitando os termos da competição. O repositório publica artefatos agregados e modelos, sem redistribuir os CSVs ou previsões individuais.\n```bash\npython scripts/prepare.py --source /path/home-credit-default-risk.zip\npython scripts/train.py\npython scripts/build_report.py\nstreamlit run app.py\n```')]
    notebook=nbformat.v4.new_notebook(cells=cells,metadata={'kernelspec':{'display_name':'Python 3','language':'python','name':'python3'}});nbformat.write(notebook,ROOT/'notebooks/01_home_credit_case.ipynb')
    print('Aggregate charts and notebook built.')
if __name__=='__main__':main()
